mapper.update:
UPDATE answer_feedback SET rating = #{record.rating}, reason = #{record.reason},
    note = #{record.note}, version = #{record.version}, updated_at = #{record.updatedAt}
WHERE run_id = #{record.runId} AND user_id = #{record.userId}
    AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE answer_feedback SET rating = NULL, reason = NULL, note = NULL,
    version = version + 1, updated_at = #{deletedAt}, deleted_at = #{deletedAt}
WHERE run_id = #{runId} AND user_id = #{userId}
    AND version = #{expectedVersion} AND deleted_at IS NULL
